import { PITCH_CLASS_LABELS } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'

export default function RootSelector() {
  const root = useSelectionStore((s) => s.selection.root)
  const setRoot = useSelectionStore((s) => s.setRoot)

  return (
    <label>
      Root note
      <select value={root} onChange={(e) => setRoot(Number(e.target.value))}>
        {PITCH_CLASS_LABELS.map((label, value) => (
          <option key={label} value={value}>
            {label}
          </option>
        ))}
      </select>
    </label>
  )
}

import { QUALITIES } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'

export default function QualitySelector() {
  const quality = useSelectionStore((s) => s.selection.quality)
  const setQuality = useSelectionStore((s) => s.setQuality)

  return (
    <label>
      Chord quality
      <select value={quality} onChange={(e) => setQuality(e.target.value as (typeof QUALITIES)[number]['id'])}>
        {QUALITIES.map((q) => (
          <option key={q.id} value={q.id}>
            {q.id}
          </option>
        ))}
      </select>
    </label>
  )
}

import { PITCH_CLASS_LABELS } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'
import type { ScaleTypeId } from '../musicCore'

const SCALE_TYPE_OPTIONS: { id: ScaleTypeId; label: string }[] = [
  { id: 'major', label: 'Major' },
  { id: 'naturalMinor', label: 'Natural minor' },
]

export default function KeyModeSelector() {
  const key = useSelectionStore((s) => s.selection.key)
  const setKeyRoot = useSelectionStore((s) => s.setKeyRoot)
  const setKeyScaleType = useSelectionStore((s) => s.setKeyScaleType)

  return (
    <details className="advanced-control">
      <summary>Advanced: key / mode</summary>
      <div className="advanced-control-body">
        <label>
          Key root
          <select value={key.root} onChange={(e) => setKeyRoot(Number(e.target.value))}>
            {PITCH_CLASS_LABELS.map((label, value) => (
              <option key={label} value={value}>
                {label}
              </option>
            ))}
          </select>
        </label>
        <label>
          Mode
          <select value={key.scaleType} onChange={(e) => setKeyScaleType(e.target.value as ScaleTypeId)}>
            {SCALE_TYPE_OPTIONS.map((o) => (
              <option key={o.id} value={o.id}>
                {o.label}
              </option>
            ))}
          </select>
        </label>
      </div>
    </details>
  )
}

import { useSelectionStore } from '../store/useSelectionStore'
import type { ScaleMode } from '../store/useSelectionStore'

const OPTIONS: { id: ScaleMode; label: string }[] = [
  { id: 'chord-root', label: 'Follow the chord root' },
  { id: 'key', label: 'Follow the selected key' },
]

export default function ScaleFollow() {
  const scaleMode = useSelectionStore((s) => s.selection.scaleMode)
  const setScaleMode = useSelectionStore((s) => s.setScaleMode)

  return (
    <fieldset>
      <legend>Scale follows</legend>
      {OPTIONS.map((o) => (
        <label key={o.id}>
          <input
            type="radio"
            name="scale-follow"
            value={o.id}
            checked={scaleMode === o.id}
            onChange={() => setScaleMode(o.id)}
          />
          {o.label}
        </label>
      ))}
    </fieldset>
  )
}

import { useSelectionStore } from '../store/useSelectionStore'

const GENRES = ['Any', 'Pop', 'Rock', 'Jazz', 'Blues', 'Classical'] as const

export default function GenreSelector() {
  const genre = useSelectionStore((s) => s.selection.genre)
  const setGenre = useSelectionStore((s) => s.setGenre)

  return (
    <label>
      Genre context
      <select value={genre} onChange={(e) => setGenre(e.target.value)}>
        {GENRES.map((g) => (
          <option key={g} value={g}>
            {g}
          </option>
        ))}
      </select>
    </label>
  )
}

