import { act } from 'react'
import { createRoot, type Root } from 'react-dom/client'
import { afterEach, beforeEach, describe, expect, it } from 'vitest'
import Keyboard from './Keyboard'
import RootSelector from './root-selector'
import QualitySelector from './quality-selector'
import KeyModeSelector from './key-mode-selector'
import ScaleFollow from './scale-follow'
import GenreSelector from './genre-selector'
import { useSelectionStore } from '../store/useSelectionStore'

let container: HTMLDivElement
let root: Root

function resetStore() {
  useSelectionStore.setState({
    selection: {
      root: 0,
      quality: 'major',
      key: { root: 0, scaleType: 'major' },
      scaleMode: 'chord-root',
      viewMode: 'both',
      genre: 'Any',
    },
    octaveStart: 48,
    octaveEnd: 71,
  })
}

beforeEach(() => {
  resetStore()
  container = document.createElement('div')
  document.body.appendChild(container)
  root = createRoot(container)
})

afterEach(() => {
  act(() => root.unmount())
  container.remove()
})

function keyStates(): Record<number, string> {
  const out: Record<number, string> = {}
  container.querySelectorAll<HTMLElement>('[data-midi]').forEach((el) => {
    out[Number(el.dataset.midi)] = el.dataset.state ?? ''
  })
  return out
}

function renderExplore() {
  act(() => {
    root.render(
      <>
        <RootSelector />
        <QualitySelector />
        <KeyModeSelector />
        <ScaleFollow />
        <GenreSelector />
        <Keyboard />
      </>,
    )
  })
}

describe('musical selectors', () => {
  it('offers all 12 chromatic roots and sets the store root on change', () => {
    renderExplore()
    const select = container.querySelector('label:has(select)')?.querySelector('select') as HTMLSelectElement
    const rootSelect = container.querySelector<HTMLSelectElement>('select[value="0"]')
    expect(rootSelect).toBeTruthy()
    act(() => {
      rootSelect!.value = '9'
      rootSelect!.dispatchEvent(new Event('change', { bubbles: true }))
    })
    expect(useSelectionStore.getState().selection.root).toBe(9)
  })

  it('changes root and re-renders the keyboard highlight set immediately', () => {
    renderExplore()
    expect(keyStates()[48]).toBe('root') // C before
    const rootSelect = container.querySelector<HTMLSelectElement>('select[value="0"]')
    act(() => {
      rootSelect!.value = '9'
      rootSelect!.dispatchEvent(new Event('change', { bubbles: true }))
    })
    const states = keyStates()
    expect(states[48]).toBe('chord-tone') // C is now a chord tone of A major
    expect(states[57]).toBe('root') // A3
  })

  it('changes quality and re-renders the keyboard highlight set immediately', () => {
    renderExplore()
    const qualitySelect = container.querySelector<HTMLSelectElement>('select[value="major"]')
    expect(qualitySelect).toBeTruthy()
    act(() => {
      qualitySelect!.value = 'm7'
