/**
 * audioEngine — Web Audio voice pool for keyboard play.
 * Browser-only, no React. Operates on MIDI note numbers.
 *
 * Contract (tech-spec §Public / integration interface contracts):
 *  - init(): Promise<void>  lazily creates + resumes the shared AudioContext;
 *    must be called from a user gesture (autoplay policy).
 *  - noteOn(midi): plays immediately; silently no-ops if not initialised or
 *    the context is not running.
 *  - noteOff(midi): releases the playing voice for that pitch.
 */

const POOL_SIZE = 16
const ATTACK_S = 0.008
const RELEASE_S = 0.12

interface Voice {
  midi: number | null
  osc: OscillatorNode | null
  gain: GainNode | null
  startedAt: number
}

let ctx: AudioContext | null = null
const voices: Voice[] = []

function midiToFrequency(midi: number): number {
  return 440 * Math.pow(2, (midi - 69) / 12)
}

function currentTime(): number {
  return ctx ? ctx.currentTime : 0
}

function makeNodes(): { osc: OscillatorNode; gain: GainNode } {
  const osc = ctx!.createOscillator()
  const gain = ctx!.createGain()
  osc.type = 'triangle'
  osc.connect(gain)
  gain.connect(ctx!.destination)
  return { osc, gain }
}

function disposeNodes(voice: Voice) {
  if (voice.osc) {
    try {
      voice.osc.stop()
    } catch {
      /* already stopped */
    }
    try {
      voice.osc.disconnect()
    } catch {
      /* already disconnected */
    }
  }
  if (voice.gain) {
    try {
      voice.gain.disconnect()
    } catch {
      /* already disconnected */
    }
  }
  voice.osc = null
  voice.gain = null
}

function acquireVoice(): Voice | null {
  if (!ctx || ctx.state !== 'running') return null
  const free = voices.find((v) => v.midi === null)
  if (free) return free
  if (voices.length < POOL_SIZE) {
    const voice: Voice = { midi: null, osc: null, gain: null, startedAt: 0 }
    voices.push(voice)
    return voice
  }
  // Steal the oldest voice so polyphony stays bounded.
  let oldest = voices[0]
  for (const v of voices) if (v.startedAt < oldest.startedAt) oldest = v
  disposeNodes(oldest)
  oldest.midi = null
  return oldest
}

export async function init(): Promise<void> {
  if (typeof window === 'undefined') throw new Error('audioEngine requires a browser')
  if (!ctx) {
    const Ctor = window.AudioContext ?? (window as unknown as { webkitAudioContext?: typeof AudioContext }).webkitAudioContext
    if (!Ctor) throw new Error('Web Audio API is not supported in this browser')
    ctx = new Ctor()
  }
  if (ctx.state === 'suspended') await ctx.resume()
}

export function isReady(): boolean {
  return ctx !== null && ctx.state === 'running'
}

export function noteOn(midi: number): void {
  if (!ctx || ctx.state !== 'running') return
  const voice = acquireVoice()
  if (!voice) return
  disposeNodes(voice)
  const { osc, gain } = makeNodes()
  osc.frequency.setValueAtTime(midiToFrequency(midi), currentTime())
  gain.gain.setValueAtTime(0.0001, currentTime())
  gain.gain.exponentialRampToValueAtTime(0.4, currentTime() + ATTACK_S)
  osc.start(currentTime())
  voice.osc = osc
  voice.gain = gain
  voice.midi = midi
  voice.startedAt = currentTime()
}

export function noteOff(midi: number): void {
  if (!ctx) return
  // Release the most recent press for this pitch; others stay sounding.
  let target: Voice | null = null
  for (const v of voices) {
    if (v.midi === midi && (!target || v.startedAt > target.startedAt)) target = v
  }
  if (!target) return
  target.midi = null
  const { osc, gain } = target
  if (!osc || !gain) return
  const t = currentTime()
  try {
    gain.gain.cancelScheduledValues(t)
    gain.gain.setValueAtTime(Math.max(gain.gain.value, 0.0001), t)
    gain.gain.exponentialRampToValueAtTime(0.0001, t + RELEASE_S)
    osc.stop(t + RELEASE_S + 0.05)
  } catch {
    /* voice already torn down */
  }
}

export function activeVoices(): number {
  return voices.reduce((n, v) => n + (v.midi !== null ? 1 : 0), 0)
}

export function poolSize(): number {
  return voices.length
}

import { useRef } from 'react'
import { chordTones, noteName, scaleTones } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'
import * as audioEngine from '../audioEngine'
import './Keyboard.css'

export type KeyState = 'root' | 'chord-tone' | 'scale-note' | 'plain'

interface KeyboardProps {
  /** When true, one-time labels on every key (outside the octave-range control). */
  showNoteNames?: boolean
}

const BLACK_OFFSETS_IN_OCTAVE = [1, 3, 6, 8, 10] as const

function midiLabel(midi: number): string {
  return `${noteName(midi % 12)}${Math.floor(midi / 12) - 1}`
}

function isBlack(midi: number): boolean {
  return (BLACK_OFFSETS_IN_OCTAVE as readonly number[]).includes(midi % 12)
}

function keyRange(startMidi: number, endMidi: number): number[] {
  const midis: number[] = []
  for (let m = startMidi; m <= endMidi; m++) midis.push(m)
  return midis
}

function classify(
  pc: number,
  root: number,
  chordSet: Set<number>,
  scaleSet: Set<number>,
  viewMode: 'chord' | 'scale' | 'both',
): KeyState {
  if (pc === root) return 'root'
  if (viewMode !== 'scale' && chordSet.has(pc)) return 'chord-tone'
  if (viewMode !== 'chord' && scaleSet.has(pc)) return 'scale-note'
  return 'plain'
}

export default function Keyboard({ showNoteNames = false }: KeyboardProps) {
  const selection = useSelectionStore((s) => s.selection)
  const storeOctaveStart = useSelectionStore((s) => s.octaveStart)
  const storeOctaveEnd = useSelectionStore((s) => s.octaveEnd)
  const setOctaveRange = useSelectionStore((s) => s.setOctaveRange)

  const held = useRef<Set<number>>(new Set())

  const { root, quality, key, scaleMode, viewMode } = selection
  const chordSet = new Set(chordTones(root, quality))
  const scaleRoot = scaleMode === 'key' ? key.root : root
  const scaleType = scaleMode === 'key' ? key.scaleType : 'major'
  const scaleSet = new Set(scaleTones(scaleRoot, scaleType))

  const midis = keyRange(storeOctaveStart, storeOctaveEnd)
  const whiteMidis = midis.filter((m) => !isBlack(m))
  const blackMidis = midis.filter(isBlack)
  const whiteCount = whiteMidis.length

  const blackLeft = (midi: number): string => {
    const idx = whiteMidis.findIndex((m) => m > midi) - 1
    return `${((idx + 0.5) / whiteCount) * 100}%`
  }

  const playNote = (midi: number) => {
    if (held.current.has(midi)) return
    held.current.add(midi)
    void audioEngine.init().then(() => audioEngine.noteOn(midi))
  }

  const stopNote = (midi: number) => {
    if (!held.current.delete(midi)) return
    audioEngine.noteOff(midi)
  }

  const keyHandlers = {
    onPointerDown: (midi: number) => () => playNote(midi),
    onPointerUp: (midi: number) => () => stopNote(midi),
    onPointerCancel: (midi: number) => () => stopNote(midi),
    onPointerLeave: (midi: number) => () => stopNote(midi),
    onKeyDown: (midi: number) => (e: React.KeyboardEvent) => {
      if ((e.key === ' ' || e.key === 'Enter') && !e.repeat) playNote(midi)
    },
    onKeyUp: (midi: number) => (e: React.KeyboardEvent) => {
      if (e.key === ' ' || e.key === 'Enter') stopNote(midi)
    },
  }

  return (
    <div className="keyboard-wrap">
      <div className="keyboard" role="group" aria-label={`Piano keyboard ${storeOctaveStart}–${storeOctaveEnd}`}>
        <div className="keyboard-whites">
          {whiteMidis.map((midi) => {
            const state: KeyState = classify(midi % 12, root, chordSet, scaleSet, viewMode)
            return (
              <button
                key={midi}
                type="button"
                className={`key key-white key-${state}`}
                data-midi={midi}
                data-state={state}
                aria-label={midiLabel(midi)}
                onPointerDown={keyHandlers.onPointerDown(midi)}
                onPointerUp={keyHandlers.onPointerUp(midi)}
                onPointerCancel={keyHandlers.onPointerCancel(midi)}
                onPointerLeave={keyHandlers.onPointerLeave(midi)}
                onKeyDown={keyHandlers.onKeyDown(midi)}
                onKeyUp={keyHandlers.onKeyUp(midi)}
              >
                <span className="key-face" aria-hidden="true">
                  {showNoteNames ? midiLabel(midi) : ''}
                </span>
                {state === 'root' && (
                  <span className="root-marker" aria-label={`${midiLabel(midi)} is the chord root`}>
                    ●
                  </span>
                )}
              </button>
            )
          })}
        </div>
        <div className="keyboard-blacks">
          {blackMidis.map((midi) => {
            const state: KeyState = classify(midi % 12, root, chordSet, scaleSet, viewMode)
            return (
              <button
                key={midi}
                type="button"
                className={`key key-black key-${state}`}
                data-midi={midi}
                data-state={state}
                aria-label={midiLabel(midi)}
                style={{ left: blackLeft(midi) }}
                onPointerDown={keyHandlers.onPointerDown(midi)}
                onPointerUp={keyHandlers.onPointerUp(midi)}
                onPointerCancel={keyHandlers.onPointerCancel(midi)}
                onPointerLeave={keyHandlers.onPointerLeave(midi)}
                onKeyDown={keyHandlers.onKeyDown(midi)}
                onKeyUp={keyHandlers.onKeyUp(midi)}
              >
                <span className="key-face" aria-hidden="true">
                  {showNoteNames ? midiLabel(midi) : ''}
                </span>
                {state === 'root' && (
                  <span className="root-marker" aria-label={`${midiLabel(midi)} is the chord root`}>
                    ●
                  </span>
                )}
              </button>
            )
          })}
        </div>
      </div>
      <label className="octave-control">
        Keyboard range
        <select
          value={`${storeOctaveStart}-${storeOctaveEnd}`}
          onChange={(e) => {
            const [start, end] = e.target.value.split('-').map(Number)
            setOctaveRange(start, end)
          }}
        >
          <option value="48-59">1 octave (C3–B3)</option>
          <option value="48-71">2 octaves (C3–B4)</option>
          <option value="48-83">3 octaves (C3–B5)</option>
          <option value="36-47">Lower octave (C2–B2)</option>
        </select>
      </label>
    </div>
  )
}

import { afterEach, beforeEach, describe, expect, it, vi } from 'vitest'
import * as audioEngine from './audioEngine'

class FakeParam {
  value = 0
  setValueAtTime = vi.fn()
  exponentialRampToValueAtTime = vi.fn()
  cancelScheduledValues = vi.fn()
}

class FakeOscillator {
  type = ''
  frequency = new FakeParam()
  started = false
  stopped = false
  connect = vi.fn(() => new FakeGain())
  start = vi.fn(() => {
    this.started = true
  })
  stop = vi.fn(() => {
    this.stopped = true
  })
  disconnect = vi.fn()
}

class FakeGain {
  gain = new FakeParam()
  connect = vi.fn()
  disconnect = vi.fn()
}

class FakeAudioContext {
  static instances: FakeAudioContext[] = []
  state: 'suspended' | 'running' = 'suspended'
  currentTime = 0
  destination = {}
  oscillators: FakeOscillator[] = []
  resume = vi.fn(() => {
    this.state = 'running'
    return Promise.resolve()
  })
  createOscillator = vi.fn(() => {
    const osc = new FakeOscillator()
    this.oscillators.push(osc)
    return osc
  })
  createGain = vi.fn(() => new FakeGain())
  constructor() {
    FakeAudioContext.instances.push(this)
  }
}

let realCtor: typeof AudioContext | undefined

beforeEach(() => {
  realCtor = window.AudioContext
  ;(window as unknown as { AudioContext?: unknown }).AudioContext = FakeAudioContext
})

afterEach(() => {
  ;(window as unknown as { AudioContext?: unknown }).AudioContext = realCtor
  vi.restoreAllMocks()
})

describe('audioEngine voice pool', () => {
  it('does not create an AudioContext before a user gesture init()', () => {
    expect(FakeAudioContext.instances).toHaveLength(0)
    audioEngine.noteOn(60)
    expect(FakeAudioContext.instances).toHaveLength(0)
  })

  it('creates and resumes the shared AudioContext on init()', async () => {
    await audioEngine.init()
    expect(FakeAudioContext.instances).toHaveLength(1)
    expect(FakeAudioContext.instances[0].resume).toHaveBeenCalled()
  })

  it('init() is idempotent — reuses the same context', async () => {
    await audioEngine.init()
    await audioEngine.init()
    expect(FakeAudioContext.instances).toHaveLength(1)
  })

  it('noteOn allocates a voice and noteOff releases it, reusing the pool', async () => {
    await audioEngine.init()
    audioEngine.noteOn(60)
    expect(audioEngine.activeVoices()).toBe(1)
    audioEngine.noteOff(60)
    expect(audioEngine.activeVoices()).toBe(0)
    audioEngine.noteOn(60)
    expect(audioEngine.activeVoices()).toBe(1)
    expect(audioEngine.poolSize()).toBeLessThanOrEqual(16)
  })

  it('plays multiple keys simultaneously (polyphony)', async () => {
    await audioEngine.init()
    audioEngine.noteOn(60)
    audioEngine.noteOn(64)
    audioEngine.noteOn(67)
    expect(audioEngine.activeVoices()).toBe(3)
    audioEngine.noteOff(64)
    expect(audioEngine.activeVoices()).toBe(2)
    expect(audioEngine.noteOff(60), 'releases only its own note').toBeUndefined()
    expect(audioEngine.activeVoices()).toBe(1)
    audioEngine.noteOff(67)
    expect(audioEngine.activeVoices()).toBe(0)
  })

  it('routes the frequency set from the MIDI pitch', async () => {
    await audioEngine.init()
    audioEngine.noteOn(69) // A4 = 440 Hz
    const ctx = FakeAudioContext.instances[0]
    expect(ctx.oscillators[0].frequency.value).toBe(440)
  })
})

