import { variationsFor } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'
import * as audioEngine from '../audioEngine'
import './VariationPanel.css'

export default function VariationPanel() {
  const selection = useSelectionStore((s) => s.selection)
  const setQuality = useSelectionStore((s) => s.setQuality)
  const setViewMode = useSelectionStore((s) => s.setViewMode)

  const { root, quality } = selection
  const variations = variationsFor(root, quality)

  const selectVariation = (id: (typeof variations)[number]['quality']) => {
    setQuality(id)
    setViewMode('both')
    void audioEngine.init().then(() => {
      audioEngine.playChord(voicingFor(id))
    })
  }

  const voicingFor = (id: (typeof variations)[number]['quality']) =>
    Array.from({ length: 0 }) // computed below without importing musicCore math inline

  return (
    <section className="variation-panel" aria-label="Chord variations">
      <h2>Variations of {`${root}`.length ? '' : ''}</h2>
      <ul className="variation-list">
        {variations.map((v) => (
          <li key={v.quality}>
            <button type="button" className="variation-item" onClick={() => selectVariation(v.quality)}>
              <span className="variation-name">{v.name}</span>
              <span className="variation-guide">{v.genreGuide[0]}</span>
            </button>
          </li>
        ))}
      </ul>
    </section>
  )
}

import { chordName, rootPositionVoice, variationsFor } from '../musicCore'
import { useSelectionStore } from '../store/useSelectionStore'
import * as audioEngine from '../audioEngine'
import './VariationPanel.css'

export default function VariationPanel() {
  const selection = useSelectionStore((s) => s.selection)
  const setQuality = useSelectionStore((s) => s.setQuality)
  const setViewMode = useSelectionStore((s) => s.setViewMode)

  const { root, quality } = selection
  const variations = variationsFor(root, quality)

  const selectVariation = (id: (typeof variations)[number]['quality']) => {
    setQuality(id)
    setViewMode('both')
    void audioEngine.init().then(() => {
      audioEngine.playChord(rootPositionVoice({ root, quality: id }))
    })
  }

  return (
    <section className="variation-panel" aria-label="Chord variations">
      <h2>Variations of {chordName(root, quality)}</h2>
      <ul className="variation-list">
        {variations.map((v) => (
          <li key={v.quality}>
            <button type="button" className="variation-item" onClick={() => selectVariation(v.quality)}>
              <span className="variation-name">{v.name}</span>
              <span className="variation-guide">{v.genreGuide[0]}</span>
            </button>
          </li>
        ))}
      </ul>
    </section>
  )
}

